using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- CalculateTotal: DataRow for inline compile-time cases ---

    [TestMethod]
    [DataRow(10.0, 1, 0.0, 10.0, DisplayName = "Single item, no tax")]
    [DataRow(10.0, 2, 0.1, 22.0, DisplayName = "Two items, 10% tax")]
    [DataRow(0.0, 5, 0.2, 0.0, DisplayName = "Zero unit price")]
    [DataRow(19.99, 0, 0.1, 0.0, DisplayName = "Zero quantity")]
    [DataRow(100.0, 1, 1.0, 200.0, DisplayName = "100% tax")]
    [DataRow(5.50, 3, 0.08, 17.82, DisplayName = "Fractional price and tax")]
    public void CalculateTotal_ReturnsExpectedResult(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- CalculateTotal: DynamicData for complex / decimal-precise cases ---

    public static IEnumerable<object[]> CalculateTotalEdgeCases
    {
        get
        {
            yield return [0m, 0, 0m, 0m];                // all zeros
            yield return [999999.99m, 100, 0.25m, 124999998.75m]; // large values
            yield return [0.01m, 1, 0.05m, 0.0105m];     // very small price
            yield return [49.99m, 3, 0.0725m, 160.8378m]; // realistic tax rate
        }
    }

    [TestMethod]
    [DynamicData(nameof(CalculateTotalEdgeCases))]
    public void CalculateTotal_EdgeCases_ReturnsExpectedResult(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }

    // --- CalculateTotal: invalid input ---

    [TestMethod]
    [DataRow(-1.0, 1, 0.1, DisplayName = "Negative unit price")]
    [DataRow(10.0, -1, 0.1, DisplayName = "Negative quantity")]
    [DataRow(10.0, 1, -0.1, DisplayName = "Negative tax rate")]
    [DataRow(10.0, 1, 1.5, DisplayName = "Tax rate > 1")]
    public void CalculateTotal_InvalidInput_ThrowsArgumentOutOfRangeException(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // --- ApplyDiscount: DataRow ---

    [TestMethod]
    [DataRow(100.0, 0.0, 100.0, DisplayName = "No discount")]
    [DataRow(100.0, 10.0, 90.0, DisplayName = "10% off")]
    [DataRow(100.0, 50.0, 50.0, DisplayName = "50% off")]
    [DataRow(100.0, 100.0, 0.0, DisplayName = "100% off (free)")]
    [DataRow(200.0, 25.0, 150.0, DisplayName = "25% off $200")]
    [DataRow(0.0, 50.0, 0.0, DisplayName = "Discount on zero price")]
    public void ApplyDiscount_ReturnsExpectedResult(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- ApplyDiscount: DynamicData via method (alternative form) ---

    public static IEnumerable<object[]> ApplyDiscountPrecisionCases()
    {
        yield return [59.99m, 15m, 50.9915m];
        yield return [9.99m, 33.33m, 6.66033m];
        yield return [1000m, 7.5m, 925m];
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountPrecisionCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_PrecisionCases_ReturnsExpectedResult(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    // --- ApplyDiscount: invalid input ---

    [TestMethod]
    [DataRow(100.0, -1.0, DisplayName = "Negative discount")]
    [DataRow(100.0, 101.0, DisplayName = "Discount > 100%")]
    public void ApplyDiscount_InvalidDiscount_ThrowsArgumentOutOfRangeException(
        double price, double discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent));
    }
}

